  LED_RED = LED6,
  LED7 = 1U,
  LED_GREEN = LED7,
  LED_NBR
} Led_TypeDef;

typedef enum
{
  BUTTON_USER = 0U,
  BUTTON_NBR
} Button_TypeDef;

typedef enum
{
